#include<bits/stdc++.h>
using namespace std;

class Solution {
public:
    string removeOuterParentheses(string s) {
        string ans = "";
        int len = s.length();
        int counter = 1;
        string builder;
        builder += s[0];

        for(int i = 1;i<=len;i++){
            
            if(counter == 0) {
        
                cout<<"adding:"<< builder.substr(1,builder.size()-2) <<"\n";
                ans += builder.substr(1,builder.size()-2);
                builder = "";
                cout << "State :  " << ans <<"\n";
            }

            if(s[i] == '(') {
                builder+=s[i];
                counter++;
            }
            if(s[i] == ')') {
                builder+=s[i];
                counter--;
            }

            cout <<"Counter :"<<counter<<endl;
        }
        return ans ;
    }
};

